using System;
using System.Drawing;
using System.Linq;
using System.Windows.Forms;
namespace Overclock {
 sealed class BenchmarkResults:UserControl {
  readonly bool gpu;readonly DataGridView grid=Theme.Grid("Metric","Value");readonly DiskScoreboard board=new DiskScoreboard{Dock=DockStyle.Top};readonly Panel resultsPanel=new Panel{Dock=DockStyle.Fill,AutoScroll=true};readonly Label state=Theme.Label("Ready when you are.",10);readonly TextBox raw=new TextBox{Dock=DockStyle.Bottom,Height=160,Multiline=true,ReadOnly=true,BackColor=Theme.Surface,ForeColor=Theme.Muted,BorderStyle=BorderStyle.None,ScrollBars=ScrollBars.Both,WordWrap=false,Visible=false,Font=new Font("Consolas",9)};readonly Button save=Theme.Button("Save PNG"),copy=Theme.Button("Copy image");string last="";bool running;
  public DiskScoreData ScoreData{get{return board.Data;}}
  public BenchmarkResults(bool isGpu){gpu=isGpu;Dock=DockStyle.Fill;BackColor=Theme.Surface;Padding=new Padding(14);resultsPanel.Controls.Add(gpu?(Control)grid:board);Controls.Add(resultsPanel);Controls.Add(raw);var bar=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink,Padding=new Padding(0,0,0,10)};state.Size=new Size(300,38);state.TextAlign=ContentAlignment.MiddleLeft;bar.Controls.Add(state);if(!gpu){save.Width=110;copy.Width=115;bar.Controls.Add(save);bar.Controls.Add(copy);var detail=Theme.Button("IOPS / latency");detail.Width=130;detail.Click+=(s,e)=>{board.Details=!board.Details;board.Invalidate();};bar.Controls.Add(detail);save.Click+=(s,e)=>SaveImage();copy.Click+=(s,e)=>CopyImage();}var log=Theme.Button("Technical log");log.Width=130;log.Click+=(s,e)=>raw.Visible=!raw.Visible;bar.Controls.Add(log);Controls.Add(bar);UpdateButtons();}
  void UpdateButtons(){save.Enabled=copy.Enabled=!running&&board.Data.HasMeasurements;}
  public void SetContext(string drive,string preset,string size,string seconds,string repeats){if(gpu||running||board.Data.HasMeasurements)return;var data=new DiskScoreData{Drive=string.IsNullOrWhiteSpace(drive)?"Select a physical drive":DiskScoreData.DriveLabel(drive),IsCopy=preset=="Copy",Settings=preset=="Copy"?size+" MiB per scenario · Filesystem copy":preset+" · "+size+" MiB · "+seconds+" s / phase · "+repeats+" measured run(s)"};string[] names=preset=="Copy"?new[]{"ISO (large files)","Program (small files)","Game (mixed files)"}:preset=="CDM Default"?new[]{"SEQ1M Q8T1","SEQ1M Q1T1","RND4K Q32T1","RND4K Q1T1"}:preset=="CDM NVMe"?new[]{"SEQ1M Q8T1","SEQ128K Q32T1","RND4K Q32T16","RND4K Q1T1"}:preset=="AS SSD inspired"?new[]{"Sequential","4K Q1T1","4K-64Thrd","Access time 512B Q1T1"}:preset=="Compression"?new[]{"Compressibility sweep"}:new[]{"Custom workload"};foreach(string name in names)data.Rows.Add(new DiskScoreRow{Name=name});board.RefreshData(data);}
  public void ResetForRun(){running=false;last="";board.RefreshData(new DiskScoreData());raw.Clear();UpdateButtons();}
  public void UpdateReport(string report,bool isRunning){if(last==report&&running==isRunning)return;last=report;running=isRunning;copy.Text="Copy image";raw.Text=report;string status=running?"Running":report.TrimEnd().EndsWith("Completed")||report.TrimEnd().EndsWith("Completed.")?"Completed":report.TrimEnd().EndsWith("Stopped")?"Stopped":report.IndexOf("Cancelled",StringComparison.OrdinalIgnoreCase)>=0?"Cancelled":"Incomplete";state.Text=running?"Running · measured phases appear below":report=="Ready"?"Ready · results in MB/s":status;state.ForeColor=running?Theme.Accent:Theme.Muted;
   if(gpu){grid.Rows.Clear();foreach(string line in report.Split('\n')){var p=line.Split(new[]{':'},2);if(p.Length==2&&(p[0].Contains("FPS")||p[0].Contains("temperature")||p[0].Contains("resolution")||p[0]=="Elapsed"||p[0]=="Frames"||p[0]=="Duration"))grid.Rows.Add(p[0].Trim(),p[1].Trim());}grid.ClearSelection();}else if(report!="Ready"){var data=DiskScoreData.FromReport(report,status);if(data.Rows.Count>0||running){if(data.Rows.Count==0)data.Rows=board.Data.Rows.Select(v=>new DiskScoreRow{Name=v.Name}).ToList();if(data.Drive=="Select a physical drive")data.Drive=board.Data.Drive;if(data.Settings=="")data.Settings=board.Data.Settings;board.RefreshData(data);}}UpdateButtons();}
  public void ShowRecord(RunRecord record){UpdateReport(record.Report,false);if(!gpu){board.RefreshData(DiskScoreData.FromRecord(record));UpdateButtons();}}
  public void ExportPng(string path){if(!board.Data.HasMeasurements||running)throw new InvalidOperationException("No finished measurements to export");board.SavePng(path);}
  void SaveImage(){using(var dialog=new SaveFileDialog{Filter="Shareable result image|*.png",FileName="BenchMark-X-results.png"})if(dialog.ShowDialog()==DialogResult.OK)try{ExportPng(dialog.FileName);}catch(Exception error){MessageBox.Show(error.Message,"Image export failed");}}
  void CopyImage(){try{using(var image=board.CreateImage())Clipboard.SetImage(image);copy.Text="Copied";}catch(Exception error){MessageBox.Show(error.Message,"Could not copy image");}}
 }
}
